export function addPlaybackFallback(media, item, parent, language) {
  const doc = media.ownerDocument;
  const note = doc.createElement("div");
  const message = doc.createElement("p");
  const link = doc.createElement("a");
  note.className = "lantern-media-fallback";
  message.hidden = true;
  message.setAttribute("role", "status");
  link.style.color = "inherit";
  link.style.textDecoration = "underline";
  link.style.fontSize = ".88rem";
  link.href = item.data;
  const mime = item.mime || item.data.slice(5, item.data.indexOf(";"));
  const ext =
    {
      "video/mp4": "mp4",
      "video/webm": "webm",
      "video/ogg": "ogv",
      "audio/mpeg": "mp3",
      "audio/mp3": "mp3",
      "audio/mp4": "m4a",
      "audio/x-m4a": "m4a",
      "audio/x-wav": "wav",
      "audio/wave": "wav",
    }[mime] ||
    mime.split("/")[1] ||
    "bin";
  const name =
    (item.name || "media")
      .replace(/[<>:"/\\\\|?*\\x00-\\x1f]/g, "")
      .trim()
      .slice(0, 160)
      .replace(/[. ]+$/, "") || "media";
  link.download = name.toLowerCase().endsWith("." + ext)
    ? name
    : name + "." + ext;
  note.append(message, link);
  parent.append(note);
  function translate(lang) {
    const zh = lang === "zh",
      video = item.kind === "video";
    if (!message.hidden)
      message.textContent = zh
        ? video
          ? "此浏览器无法播放这段视频。你可以下载原文件，用其他播放器打开。"
          : "此浏览器无法播放这段音频。你可以下载原文件，用其他播放器打开。"
        : video
          ? "This browser couldn’t play this video. Download the original to open it in another player."
          : "This browser couldn’t play this audio. Download the original to open it in another player.";
    link.textContent = zh ? "下载原文件" : "Download original file";
    link.setAttribute("aria-label", link.textContent + " · " + item.name);
  }
  function failed() {
    if (!media.error || media.error.code === 1) return;
    media.hidden = true;
    media.style.display = "none";
    message.hidden = false;
    translate(language());
  }
  media.addEventListener("error", failed);
  if (media.error) failed();
  else translate(language());
  return translate;
}
