export function createTextEngine() {
  const local = (value, lang) =>
    value?.[lang]?.trim() || value?.[lang === "zh" ? "en" : "zh"]?.trim() || "";
  function normalize(value) {
    const s = String(value ?? "")
      .normalize("NFKC")
      .toLowerCase()
      .trim()
      .replace(/[.!?,。！？、，；;]+$/u, "")
      .trim()
      .replace(/\\s+/gu, " ");
    return /^[\\p{Script=Han}\\s]+$/u.test(s) ? s.replace(/\\s/gu, "") : s;
  }
  const start = (p) => ({ passage: p.start, items: [], flags: [] });
  const passage = (p, state) => p.passages.find((s) => s.id === state.passage);
  function unmet(action, state) {
    const missing =
      action.needsItem && !state.items.includes(action.needsItem)
        ? action.needsItem
        : action.take && !state.items.includes(action.take)
          ? action.take
          : "";
    if (missing) return { type: "needsItem", id: missing };
    if (action.needsFlag && !state.flags.includes(action.needsFlag))
      return { type: "needsFlag", id: action.needsFlag };
    if (action.lacksItem && state.items.includes(action.lacksItem))
      return { type: "lacksItem", id: action.lacksItem };
    if (action.lacksFlag && state.flags.includes(action.lacksFlag))
      return { type: "lacksFlag", id: action.lacksFlag };
    return null;
  }
  function move(p, state, id) {
    const here = passage(p, state),
      action = here?.actions.find((a) => a.id === id);
    if (!action || here.ending || unmet(action, state)) return null;
    const items = new Set(state.items),
      flags = new Set(state.flags);
    if (action.take) items.delete(action.take);
    if (action.give) items.add(action.give);
    if (action.clear) flags.delete(action.clear);
    if (action.set) flags.add(action.set);
    return { passage: action.target, items: [...items], flags: [...flags] };
  }
  function command(p, state, input) {
    const value = normalize(input);
    if (!value) return { type: "empty" };
    const here = passage(p, state);
    if (!here || here.ending) return { type: "unknown" };
    const candidates = here.actions.filter((a) =>
      [
        a.label.en,
        a.label.zh,
        ...(a.aliases?.en || []),
        ...(a.aliases?.zh || []),
      ].some((w) => normalize(w) === value),
    );
    const available = candidates.filter((a) => !unmet(a, state));
    if (available.length === 1) return { type: "ok", id: available[0].id };
    if (available.length > 1 || candidates.length > 1)
      return { type: "ambiguous" };
    if (candidates.length === 1)
      return { type: "locked", reason: unmet(candidates[0], state) };
    return { type: "unknown" };
  }
  function reason(p, missing, lang) {
    if (!missing) return "";
    const item = missing.type.endsWith("Item");
    const found = (item ? p.items : p.flags).find((x) => x.id === missing.id);
    const name = local(found?.name, lang) || missing.id;
    const pairs = {
      needsItem: ["Needs " + name, "需要道具「" + name + "」"],
      needsFlag: ["Requires " + name, "需要条件「" + name + "」"],
      lacksItem: ["Already carrying " + name, "已持有「" + name + "」"],
      lacksFlag: ["Unavailable after " + name, "已触发「" + name + "」"],
    };
    return pairs[missing.type][lang === "zh" ? 1 : 0];
  }
  return { local, normalize, start, passage, move, command, unmet, reason };
}
`,Zc=`// Kept dependency-free so the same reader runs in a standalone HTML game.
export function mountTextReader(
  host,
  p,
  initialLang,
  engine,
  mediaFallback,
  onClose,
) {
  const doc = host.ownerDocument,
    node = (tag, parent, content = "", cls = "") => {
      const n = doc.createElement(tag);
      if (cls) n.className = cls;
      if (content) n.textContent = content;
      parent.append(n);
      return n;
    };
  const button = (parent, label, fn, cls = "") => {
    const b = node("button", parent, label, cls);
    b.type = "button";
    b.onclick = fn;
    return b;
  };
  let lang = initialLang === "zh" ? "zh" : "en",
    state = engine.start(p),
    history = [],
    disposed = false,
    dialog = null;
  const t = (en, zh) => (lang === "zh" ? zh : en),
    loc = (v) => engine.local(v, lang);
  const view = node("section", host, "", "tx-player");
  view.setAttribute("aria-label", loc(p.title));
  const header = node("header", view, "", "tx-player-head"),
    identity = node("div", header, "", "tx-identity"),
    tools = node("nav", header, "", "tx-tools");
  const pages = node("div", view, "", "tx-spread"),
    paper = node("article", pages, "", "tx-paper"),
    bag = node("aside", pages, "", "tx-bag");
  let heading, entry, feedback;
  const material = (id, kind) =>
    (p.materials || []).find((m) => m.id === id && m.kind === kind);
  function pause() {
    view.querySelectorAll("audio").forEach((a) => a.pause());
  }
  function closeDialog() {
    if (dialog?.open) dialog.close();
  }
  function showSheet(kind, trigger) {
    if (dialog?.open) return;
    const d = node("dialog", view, "", "tx-sheet");
    dialog = d;
    const head = node("header", d, "", "tx-sheet-head"),
      name = kind === "journal" ? t("Journal", "手记") : t("Credits", "署名");
    node("h2", head, name);
    d.setAttribute("aria-label", name);
    const close = button(head, t("Close", "关闭"), closeDialog);
    if (kind === "journal") {
      const list = node("ol", d, "", "tx-journal");
      node("li", list, loc(p.passages.find((s) => s.id === p.start).title));
      for (const turn of history) {
        const from = engine.passage(p, turn.before),
          action = from.actions.find((a) => a.id === turn.action);
        const li = node("li", list);
        node("strong", li, loc(action.label));
        if (action.target !== from.id)
          node(
            "span",
            li,
            " → " + loc(p.passages.find((s) => s.id === action.target).title),
          );
        if (loc(action.reply)) node("p", li, loc(action.reply));
      }
    } else {
      node(
        "p",
        d,
        loc(p.credits) ||
          t("No game credits have been entered.", "尚未填写游戏署名。"),
        "tx-prose",
      );
      const used = new Set(
        p.passages.flatMap((s) => [s.image, s.audio]).filter(Boolean),
      );
      for (const m of (p.materials || []).filter((m) => used.has(m.id))) {
        node("h3", d, m.name);
        node(
          "p",
          d,
          [m.credit, m.source, m.license].filter(Boolean).join(" · "),
        );
      }
    }
    d.onclose = () => {
      d.remove();
      if (dialog === d) dialog = null;
      if (!disposed) trigger.focus();
    };
    d.onkeydown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        closeDialog();
      }
    };
    d.showModal();
    close.focus();
  }
  function act(id, typed = false) {
    const next = engine.move(p, state, id);
    if (!next) return;
    history.push({ before: state, action: id });
    state = next;
    render(typed ? "command" : "heading");
  }
  function render(focus) {
    pause();
    paper.replaceChildren();
    bag.replaceChildren();
    // Keep the game's optional media-gallery trigger attached across reader turns.
    const extras = tools.querySelector(".lantern-extras-button");
    tools.replaceChildren();
    identity.replaceChildren();
    view.lang = lang === "zh" ? "zh-CN" : "en";
    view.setAttribute("aria-label", loc(p.title));
    node("span", identity, loc(p.title), "tx-book-name");
    tools.setAttribute("aria-label", t("Reader controls", "阅读工具"));
    const back = button(tools, t("Back", "上一步"), () => {
      const turn = history.pop();
      if (turn) {
        state = turn.before;
        render("heading");
      }
    });
    back.disabled = !history.length;
    const journal = button(tools, t("Journal", "手记"), () =>
      showSheet("journal", journal),
    );
    const credits = button(tools, t("Credits", "署名"), () =>
      showSheet("credits", credits),
    );
    button(tools, t("中文", "English"), () => {
      lang = lang === "en" ? "zh" : "en";
      render("heading");
    });
    if (onClose) button(tools, t("Close game", "关闭游戏"), onClose);
    if (extras) tools.append(extras);
    const here = engine.passage(p, state);
    if (here.ending) node("p", paper, t("Ending", "结局"), "tx-eyebrow");
    heading = node(
      "h1",
      paper,
      loc(here.title) || t("Untitled passage", "未命名段落"),
    );
    heading.tabIndex = -1;
    const latest = history.at(-1);
    if (latest) {
      const previous = engine.passage(p, latest.before),
        reply = loc(
          previous.actions.find((a) => a.id === latest.action)?.reply,
        );
      if (reply) node("p", paper, reply, "tx-reply");
    }
    const prose = node("div", paper, "", "tx-prose");
    for (const paragraph of loc(here.body)
      .split(/\\n\\s*\\n/)
      .filter(Boolean))
      node("p", prose, paragraph);
    const picture = material(here.image, "image");
    if (picture) {
      const fig = node("figure", paper),
        img = node("img", fig);
      img.alt = picture.name;
      img.src = picture.data;
    }
    const track = material(here.audio, "audio");
    if (track) {
      const wrap = node("div", paper, "", "tx-audio");
      node("span", wrap, track.name);
      const sound = node("audio", wrap);
      sound.controls = true;
      sound.preload = "metadata";
      sound.setAttribute("aria-label", track.name);
      mediaFallback?.(sound, track, wrap, () => lang);
      sound.src = track.data;
    }
    node("h2", bag, t("Inventory", "行囊"));
    if (!state.items.length)
      node("p", bag, t("Your pockets are empty.", "口袋里还没有东西。"));
    else {
      const ul = node("ul", bag);
      for (const id of state.items)
        node("li", ul, loc(p.items.find((x) => x.id === id)?.name));
    }
    if (state.flags.length) {
      node("h2", bag, t("Discoveries", "已知线索"));
      const ul = node("ul", bag);
      for (const id of state.flags)
        node("li", ul, loc(p.flags.find((f) => f.id === id)?.name));
    }
    entry = null;
    if (here.ending) {
      button(
        paper,
        t("Read again", "再读一次"),
        () => {
          history = [];
          state = engine.start(p);
          render("heading");
        },
        "tx-primary",
      );
    } else {
      const choices = node("section", paper, "", "tx-choices");
      node("h2", choices, t("What do you do?", "接下来做什么？"));
      for (const a of here.actions) {
        const missing = engine.unmet(a, state),
          row = node("div", choices, "", "tx-choice"),
          b = button(row, loc(a.label), () => act(a.id), "tx-action");
        if (missing) {
          b.disabled = true;
          node("small", row, engine.reason(p, missing, lang));
        }
      }
      if (!here.actions.length)
        node(
          "p",
          choices,
          t("This passage has no actions yet.", "本段尚未设置行动。"),
        );
      const form = node("form", paper, "", "tx-command");
      const label = node("label", form, t("Type a command", "输入指令"));
      entry = node("input", label);
      entry.type = "text";
      entry.maxLength = 300;
      entry.autocomplete = "off";
      entry.spellcheck = false;
      const go = node("button", form, t("Go", "执行"));
      go.type = "submit";
      feedback = node("p", form, "", "tx-feedback");
      feedback.setAttribute("role", "status");
      const commandList = node("details", paper, "", "tx-vocabulary");
      node("summary", commandList, t("Command words", "可用指令"));
      const words = node("ul", commandList);
      for (const a of here.actions) {
        const alt = a.aliases?.[lang] || [];
        node("li", words, [loc(a.label), ...alt].join(" · "));
      }
      form.onsubmit = (e) => {
        e.preventDefault();
        const match = engine.command(p, state, entry.value);
        if (match.type === "ok") {
          act(match.id, true);
          return;
        }
        feedback.textContent =
          match.type === "locked"
            ? engine.reason(p, match.reason, lang)
            : match.type === "ambiguous"
              ? t(
                  "That command matches more than one action. Choose a button above.",
                  "此指令对应多个行动，请在上方选择。",
                )
              : match.type === "empty"
                ? t(
                    "Enter a command or choose an action above.",
                    "请输入指令，或选择上方行动。",
                  )
                : t(
                    "Unknown command. Check Command words or choose an action above.",
                    "无法识别该指令。请查看可用指令，或选择上方行动。",
                  );
        entry.select();
        entry.focus();
      };
    }
    if (focus === "command" && entry) entry.focus({ preventScroll: true });
    else if (focus) {
      heading.focus({ preventScroll: true });
      view.scrollTop = 0;
    }
  }
  render("heading");
  return () => {
    disposed = true;
    pause();
    closeDialog();
    view.remove();
  };
}
