// provides its own media controls, for example in the storyboard preview.
export function addFilmCaptions(video, captions) {
  function stamp(time) {
    const ms = Math.round(time * 1000),
      seconds = Math.floor(ms / 1000);
    const part = (n) => String(n).padStart(2, "0");
    return (
      part(Math.floor(seconds / 3600)) +
      ":" +
      part(Math.floor(seconds / 60) % 60) +
      ":" +
      part(seconds % 60) +
      "." +
      String(ms % 1000).padStart(3, "0")
    );
  }
  const text = (value) =>
    value
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replace(/\\r\\n?/g, "\\n")
      .replace(/\\n{2,}/g, "\\n");
  for (const language of ["en", "zh"]) {
    const parts = [];
    for (const [i, cue] of captions.entries()) {
      if (!cue.text[language]) continue;
      // The shot ends before this final cue. The next authored cue supersedes it.
      const end = captions[i + 1]?.at ?? 172800;
      parts.push(
        stamp(cue.at) + " --> " + stamp(end) + "\\n" + text(cue.text[language]),
      );
    }
    if (!parts.length) continue;
    const track = video.ownerDocument.createElement("track");
    track.kind = "captions";
    track.srclang = language === "zh" ? "zh-CN" : "en";
    track.label = language === "zh" ? "简体中文" : "English";
    const vtt = "WEBVTT\\n\\n" + parts.join("\\n\\n") + "\\n";
    track.src =
      "data:text/vtt;charset=utf-8," +
      encodeURIComponent(
        new TextDecoder().decode(new TextEncoder().encode(vtt)),
      );
    video.append(track);
  }
}
