function stateKey(state, puzzle) {
  const position = [state.levelId,state.x,state.y];
  if (puzzle) {
    const crates = state.crates[state.levelId].map(pos => pos.x + ',' + pos.y).sort();
    return position.concat(crates).join(';');
  }
  // Pickup order is immaterial, but the locations of used keys, gates and lights are essential.
  const signature = items => [...items].sort().join(';');
  return position.concat(signature(state.takenKeys),signature(state.opened),signature(state.collected)).join('|');
}

function solveStage(project, budget) {
  const levelId = project.start, puzzle = project.kind === 'crate-puzzle';
  const level = project.levels.find(entry => entry.id === levelId);
  const result = (status,reason,visited = 0,moves = []) => ({levelId,status,reason,visited,moves});
  const floor = level.layout[level.spawn.y][level.spawn.x];
  if (!(puzzle ? '.,o' : '.,').includes(floor)) return result('incomplete','spawn');
  let viable;
  if (puzzle) {
    const layout = level.layout.join('');
    const crates = [...layout].filter(tile => tile === 'B' || tile === '*').length;
    const targets = [...layout].filter(tile => tile === 'o' || tile === '*').length;
    if (!crates || crates !== targets) return result('incomplete','crate-target-count');
    viable = viableCrateSquares(level);
  } else if (!project.levels.some(room => room.layout.some(row => row.includes('F')))) {
    return result('incomplete','missing-beacon');
  }
  if (!budget) return result('capped','budget');
  const engine = createTileEngine();
  const start = engine.start(project);
  const stranded = state => puzzle && state.crates[levelId].some(pos => !viable.has(pos.x + ',' + pos.y));
  if (stranded(start)) return result('unsolved','stranded-crate',1);
  const queue = [{state:start,parent:-1,move:''}], seen = new Set([stateKey(start,puzzle)]);
  let capped = false;
  for (let i=0; i<queue.length; i++) {
    const current = queue[i];
    if (current.state.won) {
      const moves = [];
      let entry = current;
      while (entry.parent >= 0) { moves.push(entry.move); entry = queue[entry.parent]; }
      return result('solved','win',queue.length,moves.reverse());
    }
    for (const direction of engine.directions) {
      const next = engine.step(project,current.state,direction);
      if (next.moves === current.state.moves || (next.event.type === 'push' && stranded(next))) continue;
      const key = stateKey(next,puzzle);
      if (seen.has(key)) continue;
      if (queue.length >= budget) { capped = true; continue; }
      seen.add(key);
      queue.push({state:next,parent:i,move:direction});
    }
  }
  return result(capped ? 'capped' : 'unsolved',capped ? 'budget' : 'no-route',queue.length);
}

/** Breadth-first by player move. Routes can be replayed directly with createTileEngine().step. */
export function solveTileProject(project,{maxStates = 24000} = {}) {
  const errors = validateTileProject(project).errors;
  if (errors.length) return {status:'invalid',visited:0,moves:[],stages:[],errors};
  const budget = Number.isFinite(maxStates) ? Math.min(100000,Math.max(0,Math.floor(maxStates))) : 24000;
  const stages = [];
  if (project.kind === 'tile-adventure') {
    stages.push(solveStage(project,budget));
  } else {
    const first = project.levels.findIndex(level => level.id === project.start);
    let remaining = budget;
    for (let offset=0; offset<project.levels.length; offset++) {
      const level = project.levels[(first + offset) % project.levels.length];
      const stage = solveStage({...project,start:level.id,levels:[level]}, remaining);
      stages.push(stage);
      remaining -= stage.visited;
    }
  }
  const status = ['incomplete','unsolved','capped'].find(status => stages.some(stage => stage.status === status)) || 'solved';
  return {status,stages,visited:stages.reduce((sum,stage) => sum + stage.visited,0),moves:status === 'solved' ? stages.flatMap(stage => stage.moves) : []};
}
