export function drawTileBoard(canvas, project, level, state, options = {}) {
  if (!level?.layout?.length) return;
  const rows = level.layout.length,
    cols = level.layout[0].length;
  const size = TILE_PIXELS;
  if (canvas.width !== cols * size) canvas.width = cols * size;
  if (canvas.height !== rows * size) canvas.height = rows * size;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.imageSmoothingEnabled = false;
  const player = state ?? level.spawn;
  const lockPositions = new Set(
    (level.keyLocks || []).map(({ x, y }) => x + "," + y),
  );
  const opened = new Set(state?.opened || []);
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const tile =
        state && options.cell
          ? options.cell(project, state, col, row)
          : level.layout[row][col];
      const pos = col + "," + row;
      const keyed = lockPositions.has(pos);
      drawTileCell(ctx, col * size, row * size, tile, project.kind, {
        player: !options.sprite && player?.x === col && player?.y === row,
        keyed,
        locked: keyed && !opened.has(level.id + ":" + pos),
        grid: options.grid,
        column: col,
        row,
      });
    }
  }
  if(options.sprite && player) {
    const ratio=Math.min(size/options.sprite.naturalWidth,size/options.sprite.naturalHeight);
    const w=Math.max(1,Math.round(options.sprite.naturalWidth*ratio)), h=Math.max(1,Math.round(options.sprite.naturalHeight*ratio));
    ctx.drawImage(options.sprite,player.x*size+Math.floor((size-w)/2),player.y*size+size-h,w,h);
  }
}

export function drawTilePreview(canvas, project, levelId) {
  const level =
    project.levels.find((l) => l.id === (levelId ?? project.start)) ??
    project.levels[0];
  if (level) drawTileBoard(canvas, project, level);
}
export function drawTileIcon(
  canvas,
  tile,
  kind = "tile-adventure",
  player = false,
  locked = false,
) {
  canvas.width = TILE_PIXELS;
  canvas.height = TILE_PIXELS;
  const ctx = canvas.getContext("2d");
  if (ctx) drawTileCell(ctx, 0, 0, tile, kind, { player, locked });
}
const iconCache = new Map();
export function tileImage(
  tile,
  kind = "tile-adventure",
  player = false,
  locked = false,
) {
  const key = [tile, kind, player, locked].join("/");
  if (!iconCache.has(key)) {
    const el = document.createElement("canvas");
    drawTileIcon(el, tile, kind, player, locked);
    iconCache.set(key, el.toDataURL("image/png"));
  }
  return iconCache.get(key);
}
