    const taggedIndex = name => Number(tags.find(t => t.startsWith(name + ':'))?.slice(name.length + 1))
    scene = project.scenes[taggedIndex('scene')]
    const currentLine = scene?.lines[taggedIndex('line')]
    if (!scene) return end()
    const person = people.get(currentLine?.speaker)
    audioStatus.textContent = ''
    soundButton.removeAttribute('title')
    media(scene, currentLine, person)
    sceneTitle.textContent = local(scene.title)
    speaker.hidden = !person
    speaker.textContent = person ? local(person.name) : labels.narrative
