import { randomBytes, randomUUID, timingSafeEqual } from "node:crypto";
import { pathToFileURL } from "node:url";
import { existsSync } from "node:fs";
import { gatewayPort } from "../src/generation-catalog.js";
import {
  configuredProviders,
  MediaFailure,
  renderProvider,
} from "./media-providers.mjs";

const lifetime = 15 * 60 * 1000;
const localNames = new Set(["127.0.0.1", "localhost", "[::1]"]);
export function allowedMediaOrigin(origin, env) {
  // The downloaded connector is paired with exactly the Studio that produced it.
  if (
    Object.hasOwn(env, "LANTERN_MEDIA_EXACT_ORIGIN") &&
    origin !== env.LANTERN_MEDIA_EXACT_ORIGIN
  )
    return false;
  if (origin === "null") return env.LANTERN_MEDIA_ALLOW_FILE === "1";
  try {
    const url = new URL(origin);
    if (url.origin !== origin) return false;
    if (env.LANTERN_MEDIA_EXACT_ORIGIN === origin)
      return (
        url.protocol === "https:" ||
        (url.protocol === "http:" && localNames.has(url.hostname))
      );
    if (
      ["http:", "https:"].includes(url.protocol) &&
      localNames.has(url.hostname)
    )
      return true;
    return (
      url.protocol === "https:" &&
      (env.LANTERN_MEDIA_ORIGINS || "")
        .split(",")
        .map((s) => s.trim())
        .includes(url.origin)
    );
  } catch {
    return false;
  }
}
async function getBody(req) {
  let n = 0;
  const chunks = [];
  for await (const chunk of req) {
    n += chunk.length;
    if (n > 48 * 1024) throw new MediaFailure("size");
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString());
  } catch {
    throw new MediaFailure("request");
  }
}
